using System;
using System.IO;
using CodexWatchdog;
class SessionSourceTests {
 static string root; static string file;
 static void Add(string type,string payload) { File.AppendAllText(file,"{\"timestamp\":\"2026-10-24T05:00:00Z\",\"type\":\""+type+"\",\"payload\":"+payload+"}\n"); }
 static void Output(string id,string output){Add("response_item",new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new {type="function_call_output",call_id=id,output=output}));}
 static MonitorSnapshot Read(CodexSessionSource s) { return s.Poll(DateTime.UtcNow).Snapshots[0]; }
 static void Check(bool b,string m) { if(!b){Console.WriteLine("FAIL: "+m);throw new Exception(m);} }
 static void Main(string[] args) { root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString()); Directory.CreateDirectory(Path.Combine(root,"sessions/2026/10/24")); file=Path.Combine(root,"sessions/2026/10/24/rollout-test.jsonl");
 try { File.WriteAllText(Path.Combine(root,"session_index.jsonl"),"{\"id\":\"test\",\"thread_name\":\"Synthetic title\",\"updated_at\":\"2026-10-24T00:00:00Z\"}\n"); Add("session_meta","{\"id\":\"test\",\"source\":\"vscode\",\"originator\":\"Codex Desktop\"}"); Add("event_msg","{\"type\":\"task_started\",\"turn_id\":\"a\"}");
 using(var s=new CodexSessionSource(root)) { Check(Read(s).IsGenerating,"bootstrap active");Check(Read(s).Title=="Synthetic title","index title"); Add("response_item","{\"type\":\"message\",\"role\":\"assistant\",\"content\":[{\"text\":\"error please answer\"}]}"); Check(!Read(s).HasError&&!Read(s).NeedsInput,"text never triggers"); Add("event_msg","{\"type\":\"exec_approval_request\",\"call_id\":\"approval\"}"); Check(Read(s).NeedsInput,"permission request"); Add("event_msg","{\"type\":\"exec_command_begin\"}"); Check(Read(s).NeedsInput,"unrelated activity preserves permission"); Add("event_msg","{\"type\":\"user_message\"}"); Check(!Read(s).NeedsInput,"permission user clears"); Add("response_item","{\"type\":\"function_call\",\"name\":\"functions.request_user_input_async\",\"call_id\":\"x\"}"); Check(Read(s).NeedsInput,"input"); Check(Read(s).AttentionId=="x","stable request identity");var requestUtc=Read(s).AttentionUtc;Check(requestUtc==new DateTime(2026,10,24,5,0,0,DateTimeKind.Utc),"request event time");File.AppendAllText(file,"{\"timestamp\":\"2026-10-24T06:00:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\"}}\n");Check(Read(s).AttentionUtc==requestUtc,"activity preserves request time"); Add("response_item","{\"type\":\"function_call_output\",\"call_id\":\"x\",\"output\":\"accepted\"}"); Check(Read(s).NeedsInput,"accepted remains waiting"); Add("response_item","{\"type\":\"message\",\"role\":\"user\",\"content\":[]}"); Check(!Read(s).NeedsInput,"user clears");Check(Read(s).AttentionUtc==DateTime.MinValue,"answer clears request time"); Add("response_item","{\"type\":\"function_call\",\"name\":\"request_user_input_async\",\"call_id\":\"y\"}"); Check(Read(s).NeedsInput&&Read(s).AttentionId=="y","second question same turn"); Add("response_item","{\"type\":\"message\",\"role\":\"user\"}"); Check(!Read(s).NeedsInput,"second answer clears"); File.AppendAllText(file,"{\"timestamp\":\"2026-10-24T05:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"task_complete\""); Check(Read(s).IsGenerating,"partial line"); File.AppendAllText(file,",\"turn_id\":\"a\"}}\n"); var done=Read(s); Check(done.ExplicitCompleted,"complete"); Check(Read(s).Fingerprint==done.Fingerprint,"stable fingerprint"); Add("event_msg","{\"type\":\"task_started\",\"turn_id\":\"b\"}"); Check(Read(s).IsGenerating&&!Read(s).ExplicitCompleted,"new start"); Add("event_msg","{\"type\":\"error\",\"message\":\"synthetic\"}"); Check(Read(s).HasError&&!Read(s).ExplicitCompleted,"error");Check(Read(s).AttentionUtc==new DateTime(2026,10,24,5,0,0,DateTimeKind.Utc),"error timestamp"); Add("event_msg","{\"type\":\"turn_aborted\",\"turn_id\":\"b\"}"); Check(Read(s).WasInterrupted&&!Read(s).ExplicitCompleted,"aborted not success"); File.WriteAllText(file,""); Add("session_meta","{\"id\":\"test\",\"source\":\"vscode\",\"originator\":\"Codex Desktop\"}"); Check(!Read(s).ExplicitCompleted&&!Read(s).HasError,"truncate resets"); }
 string sub=Path.Combine(Path.GetDirectoryName(file),"rollout-sub.jsonl"); File.WriteAllText(sub,"{\"type\":\"session_meta\",\"payload\":{\"id\":\"sub\",\"originator\":\"Codex Desktop\",\"source\":{\"subagent\":{}}}}\n"); using(var s=new CodexSessionSource(root))Check(Read(s).SourceId=="test","exclude subagent"); string first=file; string second=Path.Combine(Path.GetDirectoryName(file),"rollout-second.jsonl"); file=second; Add("session_meta","{\"id\":\"second\",\"source\":\"vscode\",\"originator\":\"Codex Desktop\"}"); Add("event_msg","{\"type\":\"task_started\",\"turn_id\":\"fast\"}"); Add("event_msg","{\"type\":\"task_complete\",\"turn_id\":\"fast\"}"); using(var multi=new CodexSessionSource(root)){multi.SelectedSourceId="test";var all=multi.Poll(DateTime.UtcNow);Check(all.Snapshots.Count==2,"two sources visible");var fast=all.Snapshots.Find(x=>x.SourceId=="second");Check(fast.ExplicitCompleted&&fast.TurnId=="fast"&&fast.EndedUtc!=DateTime.MinValue,"fast completion evidence");file=first;Add("response_item","{\"type\":\"function_call\",\"name\":\"request_user_input\",\"call_id\":\"first-q\"}");file=second;Add("response_item","{\"type\":\"function_call\",\"name\":\"request_user_input\",\"call_id\":\"second-q\"}");all=multi.Poll(DateTime.UtcNow.AddSeconds(2));Check(all.Snapshots.Find(x=>x.SourceId=="test").AttentionId=="first-q","first pending independent");Check(all.Snapshots.Find(x=>x.SourceId=="second").AttentionId=="second-q","second pending independent");File.Delete(first);all=multi.Poll(DateTime.UtcNow.AddSeconds(3));Check(!all.Snapshots.Find(x=>x.SourceId=="test").IsAvailable,"selected missing stays unavailable");}  using(var resolved=new CodexSessionSource(root)){Read(resolved);
 Add("response_item","{\"type\":\"function_call\",\"name\":\"functions.request_user_input\",\"call_id\":\"sync-q\",\"arguments\":\"{}\"}");
 Add("response_item","{\"type\":\"function_call\",\"name\":\"functions.request_user_input_async\",\"call_id\":\"async-q\",\"arguments\":\"{}\"}"); Read(resolved);
 Output("unrelated","{\"answers\":{\"question\":{\"answers\":[\"Yes\"]}}}"); Check(Read(resolved).AttentionId.Contains("sync-q"),"unrelated answer preserves request");
 Output("async-q","{\"accepted\":true}");Check(Read(resolved).AttentionId.Contains("async-q"),"async accepted preserves request");
 Output("sync-q","{\"answers\":{\"question\":{\"answers\":[\"Yes\"]}}}");var remaining=Read(resolved);Check(remaining.NeedsInput&&Array.IndexOf(remaining.AttentionId.Split('|'),"sync-q")<0&&remaining.AttentionId.Contains("async-q"),"sync answer clears matching only");
 Add("event_msg","{\"type\":\"exec_approval_request\",\"call_id\":\"approval-exact\",\"command\":[\"echo\",\"test\"]}");Read(resolved);
 Add("event_msg","{\"type\":\"exec_command_begin\",\"call_id\":\"other\",\"command\":[\"echo\",\"other\"]}");Check(Read(resolved).AttentionId.Contains("approval-exact"),"unrelated begin preserves approval");
 Add("event_msg","{\"type\":\"exec_command_begin\",\"call_id\":\"approval-exact\",\"command\":[\"echo\",\"test\"]}");remaining=Read(resolved);Check(remaining.NeedsInput&&!remaining.AttentionId.Contains("approval-exact")&&remaining.AttentionId.Contains("async-q"),"matching begin resolves approval only");
 Add("event_msg","{\"type\":\"user_message\"}");Check(!Read(resolved).NeedsInput,"final answer resolves remainder"); Add("response_item","{\"type\":\"function_call\",\"name\":\"request_user_input\",\"call_id\":\"only-sync\",\"arguments\":\"{}\"}");Read(resolved);Output("only-sync","{\"answers\":{\"question\":{\"answers\":[\"Done\"]}}}");Check(!Read(resolved).NeedsInput&&Read(resolved).AttentionUtc==DateTime.MinValue,"last sync answer clears attention");Add("event_msg","{\"type\":\"apply_patch_approval_request\",\"call_id\":\"patch-exact\"}");Read(resolved);Add("event_msg","{\"type\":\"patch_apply_begin\",\"call_id\":\"patch-exact\"}");Check(!Read(resolved).NeedsInput,"matching patch begin clears approval");
 } Add("event_msg","{\"type\":\"task_started\",\"turn_id\":\"long-active\"}");string padding=new String('x',8192);for(int i=0;i<160;i++)Add("response_item","{\"type\":\"reasoning\",\"summary\":[{\"type\":\"summary_text\",\"text\":\""+padding+"\"}]}");
 using(var longTurn=new CodexSessionSource(root)){longTurn.SelectedSourceId="another-selected-chat";var before=Read(longTurn);Check(before.IsGenerating&&!before.ExplicitCompleted,"all-source 8MiB bootstrap recognizes active turn");longTurn.SelectedSourceId="second";var after=Read(longTurn);Check(after.IsGenerating&&after.TurnId=="long-active","selected bootstrap recovers start beyond 1MiB");Check(Read(longTurn).Fingerprint==after.Fingerprint,"selected expanded baseline only once");}
 using(var initiallySelected=new CodexSessionSource(root)){initiallySelected.SelectedSourceId="second";Check(Read(initiallySelected).IsGenerating,"initial selected uses expanded bootstrap");}Console.WriteLine("Session source tests passed"); if(args.Length>0)using(var real=new CodexSessionSource(args[0])){if(args.Length>1)real.SelectedSourceId=args[1];var r=real.Poll(DateTime.UtcNow);Console.WriteLine("Real source found="+(r.Snapshots.Count>0));if(r.Snapshots.Count>0)Console.WriteLine("generating="+r.Snapshots[0].IsGenerating+"; input="+r.Snapshots[0].NeedsInput+"; completed="+r.Snapshots[0].ExplicitCompleted);} } finally { Directory.Delete(root,true); } }
}
